const GREETINGS: Record<Language, string> = {
  en: "Hello! I'm DR.AI, your AI Health Companion. I specialize in natural home remedies and wellness. How can I assist you today?",
  hi: "αñ¿αñ«αñ╕! αñ« DR.AI αñ╣, αñåαñ¬αñò AI αñ╕αñ╕ αñ╕αñÑαÑñ αñ« αñ¬αñòαññαñò αñÿαñ░αñ▓ αñëαñ¬αñÜαñ░ αñ« αñ╡αñ╢αñ╖αñ£ αñ╣αÑñ αñ« αñåαñ£ αñåαñ¬αñò αñòαñ╕ αñ«αñªαñª αñòαñ░ αñ╕αñòαññ αñ╣?",
  ta: "α«╡α«úα«òα«òα««! α«¿α«⌐ DR.AI, α«ëα«Öα«òα«│ AI α«Üα«òα«ñα«░ α«ñα«ú. α«çα«»α«▒α«ò α«╡α«ƒα«ƒ α«╡α«ñα«ñα«»α«ñα«ñα«▓ α«¿α«⌐ α«¿α«¬α«úα«⌐.",
  te: "α░¿α░«α░╕α░░! α░¿α░¿ DR.AI, α░« AI α░åα░░α░ù α░╕α░╣α░Üα░░α░íα░¿. α░¿α░¿ α░╕α░╣α░£ α░çα░ƒ α░¿α░╡α░░α░úα░▓α░▓ α░¿α░¬α░úα░íα░¿.",
